import static org.junit.Assert.*;

public class GJChronology_getInstance_TriageGen2Test {











    @Test
    public void testGetInstance_CachingMechanism() {
        // Tests the loop and cache hit logic
        DateTimeZone zone = DateTimeZone.UTC;
        int minDays = 4;
        Instant cutover = new Instant(1000000000L);

        // First call: creates new
        GJChronology chrono1 = GJChronology.getInstance(zone, cutover, minDays);

        // Second call: should hit the cache (same zone, same cutover, same minDays)
        GJChronology chrono2 = GJChronology.getInstance(zone, cutover, minDays);

        assertSame("Should return the cached instance", chrono1, chrono2);
    }




}

