public class GJChronology_getInstance_TriageGen2Test {













    @Test
    public void testGetInstance_CacheMissDifferentParams() {
        // Tests that different parameters result in different objects (not hitting cache)
        DateTimeZone zone = DateTimeZone.UTC;
        Instant cutover = new Instant(1000000000L);

        GJChronology chrono1 = GJChronology.getInstance(zone, cutover, 4);

        // Different minDaysInFirstWeek
        GJChronology chrono2 = GJChronology.getInstance(zone, cutover, 5);

        // Different cutover
        GJChronology chrono3 = GJChronology.getInstance(zone, new Instant(2000000000L), 4);

        assertNotSame(chrono1, chrono2);
        assertNotSame(chrono1, chrono3);
    }


}

